}

ll ceil_sqrt(ll x) {
    ll s = floor_sqrt(x);
    if (s * s == x) return s;
    return s + 1;
}

ll floor_b(ll x) {
    ll s = floor_sqrt(4 * x + 1);
    return (s - 1) / 2;
}

ll ceil_b(ll x) {
    ll k = floor_b(x);
    if (k * (k + 1) < x) k++;
    return k;
}

